import{_ as n,c as r,a3 as e,o as l}from"./chunks/framework.BNJ_-Amg.js";const s="/local/operation/auto_dashboard.png",i="/local/operation/autorun_button.png",u="/local/operation/battery_pcs_status.png",c="/local/operation/man_dashboard.png",h="/local/operation/pcs_man_button.png",o="/local/operation/on_button.png",a="/local/operation/off_button.png",p="/local/operation/clear_fault_button.png",g="/local/operation/generator_control_button.png",y=JSON.parse('{"title":"Normal Operation","description":"","frontmatter":{},"headers":[],"relativePath":"local/operation.md","filePath":"local/operation.md"}'),m={name:"local/operation.md"};function d(f,t,b,_,q,O){return l(),r("div",null,t[0]||(t[0]=[e('<h1 id="normal-operation" tabindex="-1">Normal Operation <a class="header-anchor" href="#normal-operation" aria-label="Permalink to &quot;Normal Operation&quot;">​</a></h1><h2 id="auto-mode" tabindex="-1">Auto Mode <a class="header-anchor" href="#auto-mode" aria-label="Permalink to &quot;Auto Mode&quot;">​</a></h2><p>In <strong>Auto Mode</strong>, when the <strong>ON</strong> button is pressed, all devices will start automatically in the designated sequence. Similarly, pressing the <strong>OFF</strong> button will stop all devices in reverse order.</p><p><img src="'+s+'" alt="auto_dashboard"></p><ol><li>Turn the <strong>Panel Power Switch</strong> to the <strong>ON</strong> position, set the <strong>MAN/AUTO</strong> Switch to <strong>Auto</strong>.</li><li>On the <strong>HMI</strong>, under <strong>Auto Run</strong>, press <strong>ON</strong> button.<img src="'+i+'" alt="autorun_button"></li><li>The system will automatically initiate the start-up sequence.</li><li>After 2-3 minutes, the <strong>Battery Status</strong> and <strong>PCS Status</strong> will show either &quot;Discharging&quot; or &quot;Charging,&quot; confirming that the system is functioning normally. <img src="'+u+'" alt="battery_pcs_status"></li></ol><h2 id="manual-mode" tabindex="-1">Manual Mode <a class="header-anchor" href="#manual-mode" aria-label="Permalink to &quot;Manual Mode&quot;">​</a></h2><p>In manual mode, users can individually control the operation of each device. To enable manual mode, rotate the <strong>MAN/AUTO</strong> switch to the <strong>&quot;MAN&quot;</strong> position.</p><p><img src="'+c+'" alt="Manual_dashboard"></p><h3 id="power-conversion-system-pcs-manual-control" tabindex="-1">Power Conversion System (PCS) manual control <a class="header-anchor" href="#power-conversion-system-pcs-manual-control" aria-label="Permalink to &quot;Power Conversion System (PCS) manual control&quot;">​</a></h3><p><img src="'+h+'" alt="pcs_man_button"></p><h4 id="turn-on" tabindex="-1">Turn On <a class="header-anchor" href="#turn-on" aria-label="Permalink to &quot;Turn On&quot;">​</a></h4><p>Long press “ON” Button <img src="'+o+'" alt="OnButton"> to turn on the PCS manually. The “ON” Button will light on, the “OFF” button will light off.</p><h4 id="turn-off" tabindex="-1">Turn off <a class="header-anchor" href="#turn-off" aria-label="Permalink to &quot;Turn off&quot;">​</a></h4><p>Long press “OFF” button <img src="'+a+'" alt="offButton"> to turn off the PCS manually. The “OFF” Button will light on, the “ON” button will light off.</p><h4 id="manual-clear-fault" tabindex="-1">Manual Clear Fault <a class="header-anchor" href="#manual-clear-fault" aria-label="Permalink to &quot;Manual Clear Fault&quot;">​</a></h4><p>When the system detects a fault, and shut down, user can switch to manual to clear the fault to reboot the battery. To clear the fault, long press the “Clear Fault” button. <img src="'+p+'" alt="clear_fault_button"></p><h3 id="generator-manual-control" tabindex="-1">Generator manual control <a class="header-anchor" href="#generator-manual-control" aria-label="Permalink to &quot;Generator manual control&quot;">​</a></h3><p><img src="'+g+'" alt="generator_control_button"> The generator manual control section allows user to start/stop the generator manually.</p><h4 id="turn-on-1" tabindex="-1">Turn On <a class="header-anchor" href="#turn-on-1" aria-label="Permalink to &quot;Turn On&quot;">​</a></h4><p>Long press <strong>“ON”</strong> Button <img src="'+o+'" alt="OnButton"> to turn on the PCS manually. The <strong>“ON”</strong> Button will light on, the <strong>“OFF”</strong> button will light off. Generator will strat running.</p><h4 id="turn-off-1" tabindex="-1">Turn off <a class="header-anchor" href="#turn-off-1" aria-label="Permalink to &quot;Turn off&quot;">​</a></h4><p>To manually turn off the battery, long press the <strong>&quot;OFF&quot;</strong> button <img src="'+a+'" alt="offButton">. Once the battery is turned off, the <strong>&quot;OFF&quot;</strong> button will illuminate, and the <strong>&quot;ON&quot;</strong> button will no longer be lit. Generator stop running.</p>',22)]))}const P=n(m,[["render",d]]);export{y as __pageData,P as default};
